    def inbb(cell,c): return abs(cell[0]-c[0])<=2 and abs(cell[1]-c[1])<=2
    def ok(pos,x):
        for p in pos:
            if dc2(p)&OBS: return False
        return not (xc2(x)&OBS)
    def goal(pos): return bool(xc2(disc(pos))&D)
    def nbrs(st):
        pos,pl=st; x=disc(pos); out=[]
        for i in range(n):
            if i!=pl: out.append((pos,i))
        allb=list(pos)+list(blockers)
        for dr in range(-2,3):
            for dk in range(-2,3):
                cell=(x[0]+dr,x[1]+dk)
                if any(inbb(cell,c) for c in allb): continue
                np_=list(pos); np_[pl]=cell; np_=tuple(np_)
                if ok(np_,disc(np_)): out.append((np_,pl))
        if not any(inbb(R,c) for c in allb):
            np_=list(pos); np_[pl]=R; np_=tuple(np_)
            if ok(np_,disc(np_)): out.append((np_,pl))
        return out
    def h(st):
        x=disc(st[0]); return max(abs(x[0]-R[0]),abs(x[1]-R[1]))//wgt+ (0 if not goal(st) else -5)
    st=(tuple(pos),p0)
    if goal(st): return []
    pq=[(h(st),0,st)]; best={st:0}; par={}; exp=0
    while pq:
        _,g,s=heapq.heappop(pq)
        if best.get(s,99)<g: continue
        exp+=1
        if exp>cap: return None
        for ns in nbrs(s):
            if best.get(ns,999)<=g+1: continue
            best[ns]=g+1; par[ns]=s
            if goal(ns):
                path=[]; cur=ns
                while cur in par: path.append(cur); cur=par[cur]
                return path
            heapq.heappush(pq,(g+1+h(ns),g+1,ns))
    return None
