def ach(f, pos, p0, ringc, dashes, blockers, maxd=24, cap=200000, wgt=2):
    import heapq
    a=f.ascii.split('\n')
    OBS=set((i,j) for i in range(64) for j in range(64) if a[i][j] in ('S','g'))
    D=set(dashes); R=ringc; n=len(pos)
    def dsc(p): return (sum(q[0] for q in p)//n, sum(q[1] for q in p)//n)
    def inbb(cell,c): return abs(cell[0]-c[0])<=2 and abs(cell[1]-c[1])<=2
    def ok(np_,x):
        for p in np_:
            if dc2(p)&OBS: return False
        return not (xc2(x)&OBS)
    def goalp(np_): return bool(xc2(dsc(np_))&D)
    def nbrs(st):
        np_,pl=st; x=dsc(np_); out=[]
        for i in range(n):
            if i!=pl: out.append((np_,i))
        allb=list(np_)+list(blockers)
        for dr in range(-2,3):
            for dk in range(-2,3):
                cell=(x[0]+dr,x[1]+dk)
                if any(inbb(cell,c) for c in allb): continue
                nn=list(np_); nn[pl]=cell; nn=tuple(nn)
                if ok(nn,dsc(nn)): out.append((nn,pl))
        if not any(inbb(R,c) for c in allb):
            nn=list(np_); nn[pl]=R; nn=tuple(nn)
            if ok(nn,dsc(nn)): out.append((nn,pl))
        return out
    def hst(st):
        x=dsc(st[0]); d=max(abs(x[0]-R[0]),abs(x[1]-R[1]))
        return 0 if goalp(st[0]) else max(1,d//wgt)
    st=(tuple(pos),p0)
    if goalp(st[0]): return []
    pq=[(hst(st),0,st)]; best={st:0}; par={}; exp=0
    while pq:
        _,g,s=heapq.heappop(pq)
        if best.get(s,99)<g: continue
        if g>=maxd: continue
        exp+=1
        if exp>cap: return ('cap',exp)
        for ns in nbrs(s):
            if best.get(ns,999)<=g+1: continue
            best[ns]=g+1; par[ns]=s
            if goalp(ns[0]):
                path=[]; cur=ns
                while cur in par: path.append(cur); cur=par[cur]
                return ('ok',path,exp)
            heapq.heappush(pq,(g+1+hst(ns),g+1,ns))
    return ('none',exp)
