def solve_chain(f, pos, other, p0, dashes, rings, maxd=30, cap=400000, wdiv=2):
    import heapq
    S=env(f)
    dash=set(dashes)
    n=len(pos)
    def disc(p): return (sum(q[0] for q in p)//n, sum(q[1] for q in p)//n)
    def valid(p,x):
        for q in p:
            if not(3<=q[0]<=60 and 3<=q[1]<=60): return False
            if dc2(q)&S: return False
        return not (xc2(x)&S)
    def nbrs(st):
        p,pl=st; x=disc(p); out=[]
        for i in range(n):
            if i!=pl: out.append((p,i))
        allb=list(p)+list(other)
        cells=[(x[0]+dr,x[1]+dk) for dr in (-2,0,2) for dk in (-2,0,2)]
        for cell in cells:
            if any(abs(cell[0]-q[0])<=2 and abs(cell[1]-q[1])<=2 for q in allb): continue
            np_=list(p); np_[pl]=cell; np_=tuple(np_)
            if valid(np_,disc(np_)): out.append((np_,pl))
        for rc in rings:
            if any(abs(rc[0]-q[0])<=2 and abs(rc[1]-q[1])<=2 for q in allb): continue
            np_=list(p); np_[pl]=rc; np_=tuple(np_)
            if valid(np_,disc(np_)): out.append((np_,pl))
        return out
    def h(st):
        x=disc(st[0])
        return min(max(abs(x[0]-d[0]),abs(x[1]-d[1])) for d in dash)//wdiv
    st=(pos,p0)
    if xc2(disc(pos))&dash: return []
    pq=[(h(st),0,st)]; best={st:0}; par={}; exp=0
    while pq:
        _,g,s=heapq.heappop(pq)
        if best.get(s,99)<g: continue
        exp+=1
        if exp>cap: return None
        for ns in nbrs(s):
